export function buildLevel(id){
 const d=definitions.find(x=>x.id===id);if(!d)throw Error('unknown level');
 if(d.frozenMapCode){const decoded=DataSerializer.loadFromShareCode(d.frozenMapCode);if(!decoded.success)throw Error(decoded.error);return decoded.data.mapData;}
 if(d.variantOf){const m=buildLevel(d.variantOf);if(d.variant!=='reverse-exit-without-letter-control')throw Error('unknown course variant');m.layers[0].buttons=[];m.layers[0].vWalls[2][4]=wall(W.EMPTY);m.layers[0].vWalls[2][5]=wall(W.ONE_WAY,{direction:{dx:-1,dy:0}});return normalizeVoidWalls(normalizeMapData(m));}
 if(!d.galleryTitle)return room(d.width,d.height,d.params);
 const r=DataSerializer.loadFromShareCode(gallerySources[d.galleryTitle].mapCode);if(!r.success)throw Error(r.error);
 const m=r.data.mapData,l=m.layers[0];
 if(d.galleryVariant==='focus-terminal-guard'){
  l.ghosts.splice(0,1);for(let x=2;x<=5;x++)l.activeCells[0][x]=false;
 }
 if(['seal-exterior','quiet-start-with-key-approach','focus-terminal-guard'].includes(d.galleryVariant)){
  for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++)if(l.activeCells[y][x])for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]])if(!l.activeCells[y+dy]?.[x+dx])l[(dx?'v':'h')+'Walls'][y+(dy===1?1:0)][x+(dx===1?1:0)]=wall(W.SOLID);
 }
 if(d.galleryVariant==='quiet-start-with-key-approach'){l.customStartPos={x:1,y:2};l.hWalls[1][3]=wall(W.LETTER_DOOR,{letter:'A',initialState:'closed'});}
 if(d.goalExtension){
  const[x,y]=d.goalExtension,old=l.endPos;if(l.activeCells[y][x]||Math.abs(x-old.x)+Math.abs(y-old.y)!==1)throw Error('goal extension must be a new adjacent cell');
  l.activeCells[y][x]=true;l.endPos={x,y};
  for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]])l[(dx?'v':'h')+'Walls'][y+(dy===1?1:0)][x+(dx===1?1:0)]=wall(x+dx===old.x&&y+dy===old.y?W.EMPTY:W.SOLID);
 }
 return normalizeVoidWalls(normalizeMapData(m));
}
export function sourceMapCode(id){const d=definitions.find(x=>x.id===id);return d.galleryTitle&&!d.galleryVariant?gallerySources[d.galleryTitle].mapCode:null;}
